"""Browser end-to-end: flows A (flood), B (election), C (invalid), D (persistence).
Usage: python3 e2e/run.py http://localhost:4173/ [shots_dir]"""
import sys, json, os
from playwright.sync_api import sync_playwright
url = sys.argv[1] + ('?play' if '?' not in sys.argv[1] else ''); shots = sys.argv[2] if len(sys.argv) > 2 else 'e2e/shots'
os.makedirs(shots, exist_ok=True)
errors = []; fails = []
def check(name, cond, info=''):
    print(('PASS ' if cond else 'FAIL ') + name + (f'  [{info}]' if info != '' else ''))
    if not cond: fails.append(name)
def state(pg, js): return pg.evaluate(js)
with sync_playwright() as p:
    b = p.chromium.launch(args=["--use-gl=angle","--use-angle=swiftshader","--enable-unsafe-swiftshader","--ignore-gpu-blocklist"])
    ctx = b.new_context(viewport={"width":1360,"height":800})
    pg = ctx.new_page()
    pg.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
    pg.on("pageerror", lambda e: errors.append("PAGEERROR " + str(e)))
    pg.goto(url); pg.wait_for_function("window.agerous && window.agerous.world", timeout=15000); pg.wait_for_timeout(1500)
    pg.screenshot(path=f'{shots}/01_normal_walk.png')
    check('A0 world boots at Day 1 morning', state(pg, "agerous.world.t >= 480 && agerous.world.t < 700"))
    pg.evaluate("agerous.player.toggleMode()"); pg.wait_for_timeout(600)
    pg.screenshot(path=f'{shots}/02_normal_sky.png')
    # ---- Flow A: flood via the real prompt box
    pg.fill('#prompt-input', 'A severe flood is coming'); pg.click('#prompt-go'); pg.wait_for_timeout(800)
    check('A1 interpretation card shown', 'flood' in pg.inner_text('#interp').lower(), pg.inner_text('#interp')[:80].replace('\n',' | '))
    check('A2 world has a rain event & forecast', state(pg, "agerous.world.env.peak") > 2.7)
    pg.evaluate("agerous.world.timeSpeed = 90"); pg.wait_for_timeout(9000)
    w = state(pg, "({stage: agerous.world.env.stage, school: agerous.world.institutions.school.open, market: agerous.world.institutions.market.open, shelters: agerous.world.institutions.civil.shelters, church: Object.values(agerous.world.npcs).filter(n=>n.location==='church').length})")
    check('A3 water rose', w['stage'] > 1.0, w['stage'])
    pg.screenshot(path=f'{shots}/03_flood_sky.png')
    pg.evaluate("agerous.player.toggleMode()"); pg.wait_for_timeout(500)
    pg.screenshot(path=f'{shots}/04_flood_walk.png')
    pg.wait_for_timeout(9000)
    w = state(pg, "({stage: agerous.world.env.stage, school: agerous.world.institutions.school.open, market: agerous.world.institutions.market.open, shelters: agerous.world.institutions.civil.shelters, church: Object.values(agerous.world.npcs).filter(n=>n.location==='church').length})")
    check('A4 school closed by rule', w['school'] is False if isinstance(w['school'], bool) else not w['school'])
    check('A5 civil defence opened a shelter and people are in it', w['shelters'] == ['church'] and w['church'] >= 20, json.dumps(w))
    check('A6 history shows the causal chain', all(k in pg.inner_text('#history') for k in ['Evacuation ordered', 'shelter', 'School closed']))
    pg.screenshot(path=f'{shots}/05_flood_ui.png')
    # ---- Flow D: persistence
    pg.evaluate("agerous.world.timeSpeed = 0"); pg.wait_for_timeout(300)
    snap = state(pg, "({t: agerous.world.t, stage: +agerous.world.env.stage.toFixed(3), hist: agerous.world.history.length})")
    pg.reload(); pg.wait_for_function("window.agerous && window.agerous.world", timeout=15000); pg.wait_for_timeout(800)
    snap2 = state(pg, "({t: agerous.world.t, stage: +agerous.world.env.stage.toFixed(3), hist: agerous.world.history.length})")
    check('D1 reload restores clock, flood level and history', snap2['t'] == snap['t'] and abs(snap2['stage']-snap['stage'])<0.02 and snap2['hist'] >= snap['hist'], f'{snap} -> {snap2}')
    # ---- Flow C: invalid prompt leaves world unchanged
    pg.evaluate("agerous.world.timeSpeed = 0")
    before = state(pg, "JSON.stringify([agerous.world.env, agerous.world.institutions])")
    pg.fill('#prompt-input', 'summon a dragon over the church'); pg.click('#prompt-go'); pg.wait_for_timeout(600)
    after = state(pg, "JSON.stringify([agerous.world.env, agerous.world.institutions])")
    check('C1 unsupported prompt: useful error shown', 'flood' in pg.inner_text('#interp').lower() and "couldn't" in pg.inner_text('#interp').lower(), pg.inner_text('#interp')[:100].replace('\n',' | '))
    check('C2 unsupported prompt: world unchanged', before == after)
    # ---- Flow B: election on a fresh world
    pg.evaluate("localStorage.clear()"); pg.once("dialog", lambda d: d.accept()); pg.click('#btn-new'); pg.wait_for_timeout(500)
    pg.fill('#prompt-input', 'The local election is tomorrow'); pg.click('#prompt-go'); pg.wait_for_timeout(600)
    check('B1 election called', state(pg, "agerous.world.institutions.election.state") == 'campaign')
    pg.evaluate("agerous.world.timeSpeed = 360"); pg.wait_for_timeout(7000)
    pg.screenshot(path=f'{shots}/06_campaign_sky.png') if False else None
    for _ in range(70):
        if state(pg, "agerous.world.institutions.election.state") == 'done': break
        pg.wait_for_timeout(1000)
    pg.wait_for_timeout(800)
    r = state(pg, "agerous.world.elections.at(-1)")
    check('B2 election concluded with tally & turnout', bool(r) and r['total'] > 5, json.dumps(r))
    check('B3 result in history', 'wins the local election' in pg.inner_text('#history'))
    # ---- Flow E: build a structure from a sentence; Flow F: talk to a resident
    pg.evaluate("agerous.world.timeSpeed = 0")
    pg.fill('#prompt-input', 'build a levee around the church'); pg.click('#prompt-go'); pg.wait_for_timeout(800)
    check('E1 build event interpreted', 'build' in pg.inner_text('#interp').lower(), pg.inner_text('#interp')[:80].replace('\n',' | '))
    check('E2 defence stored in world state', state(pg, "agerous.world.env.defenses.church") == 1.0)
    pg.wait_for_timeout(2200)
    check('E3 3D structure exists in the scene', state(pg, "Object.keys(agerous.scene.defenseMeshes||{}).includes('church')"))
    pg.screenshot(path=f'{shots}/07_build.png')
    pg.evaluate("agerous.ui.npcCard(Object.values(agerous.world.npcs)[0], agerous.world)"); pg.wait_for_timeout(300)
    pg.fill('#npc-q', 'are you safe?'); pg.press('#npc-q', 'Enter'); pg.wait_for_timeout(800)
    check('F1 resident replies in character', len(pg.inner_text('#npc-reply')) > 10, pg.inner_text('#npc-reply')[:80])
    # ---- Flow G: Storm Day challenge -> verified leaderboard -> chat (needs `node server/proxy.mjs` on :8787)
    pg.evaluate("agerous.startChallenge()"); pg.wait_for_timeout(500)
    check('G1 challenge world: storm + blocked market + closed school scripted', state(pg, "agerous.world.institutions.school.open === false && agerous.world.env.peak > 2.7"))
    pg.fill('#prompt-input', 'send in the clean-up crews'); pg.click('#prompt-go'); pg.wait_for_timeout(800)
    check('G2 sentence recorded for server replay', state(pg, "agerous.world.scenario.run.length") == 1 and 'left' in pg.inner_text('#chal-left'), pg.inner_text('#chal-left'))
    pg.evaluate("agerous.world.timeSpeed = 720")
    for _ in range(90):
        if pg.is_visible('#result'): break
        pg.wait_for_timeout(1000)
    check('G3 scenario ends exactly at the end of Day 4 and shows a result', pg.is_visible('#result') and state(pg, "agerous.world.t") == 5760, str(state(pg, "agerous.world.t")))
    pg.wait_for_timeout(2500)
    res = pg.inner_text('#result-box').replace('\n', ' | ')
    check('G4 server-verified rank shown', 'Rank' in res and 'verified' in res, res[:120])
    pg.click('#res-board'); pg.wait_for_timeout(1200)
    check('G5 leaderboard lists the run', 'safety' in pg.inner_text('#board'), pg.inner_text('#board')[:80].replace('\n', ' '))
    pg.screenshot(path=f'{shots}/08_leaderboard.png')
    pg.click('#drawer .tabs button[data-tab=chat]'); pg.fill('#chat-input', 'hello from the e2e test'); pg.press('#chat-input', 'Enter'); pg.wait_for_timeout(1500)
    check('G6 chat message round-trips', 'hello from the e2e test' in pg.inner_text('#chat-log'))
    pg.screenshot(path=f'{shots}/09_chat.png')
    import urllib.request
    try:
        h = json.load(urllib.request.urlopen('http://localhost:8787/health', timeout=5))
        print(f"INFO storage behind the proxy: durable={h['store']['durable']} reachable={h['store']['reachable']} (set KV_REST_API_URL/TOKEN or run scripts/fake-upstash.mjs to exercise the durable path)")
        check('G7 chat/leaderboard notice matches the storage mode', ('Demo storage' not in pg.inner_text('#chat-note')) == h['store']['durable'], pg.inner_text('#chat-note')[:60])
    except Exception as e: print('INFO health check skipped:', e)
    # ---- Flow H: sound, wellbeing graph, lightning, mobile touch controls
    pg.click('#btn-sound'); muted = state(pg, "agerous.sound.muted"); pg.click('#btn-sound')
    check('H1 sound toggle mutes and unmutes, audio context runs', muted is True and state(pg, "agerous.sound.muted") is False and state(pg, "agerous.sound.ctx && agerous.sound.ctx.state") == 'running')
    check('H2 wellbeing graph is sampling the world', state(pg, "agerous.ui._tr && agerous.ui._tr.pts.length") >= 1)
    lum = state(pg, """(async()=>{const s=agerous.scene,l=()=>{const c=s.scene.background;return c.r+c.g+c.b};const base=l();let mx=base;s._flash=1;
        await new Promise(r=>{const t0=performance.now();const f=()=>{mx=Math.max(mx,l());performance.now()-t0>900?r():requestAnimationFrame(f)};f()});return mx-base})()""")
    check('H3 lightning flash brightens the sky', lum > 0.1, round(lum, 3))
    pg.close()                                   # software WebGL: don't render two scenes at once
    m = b.new_context(viewport={"width":390,"height":844}, has_touch=True, is_mobile=True).new_page()
    m.on("pageerror", lambda e: errors.append("MOBILE PAGEERROR " + str(e)))
    m.goto(sys.argv[1] + '?play'); m.wait_for_function("window.agerous && window.agerous.world", timeout=45000); m.wait_for_timeout(1000)
    check('H4 phone gets touch UI: joystick visible, chips scroll', m.evaluate("document.body.classList.contains('touch') && getComputedStyle(document.getElementById('joystick')).display === 'block' && document.getElementById('chips').scrollWidth > document.getElementById('chips').clientWidth"))
    x0, z0 = m.evaluate("[agerous.player.x, agerous.player.z]")
    m.evaluate("""()=>{const pad=document.getElementById('joystick'),r=pad.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;
        const ev=(t,x,y)=>pad.dispatchEvent(new PointerEvent(t,{pointerId:7,clientX:x,clientY:y,bubbles:true,isPrimary:true}));
        pad.setPointerCapture=()=>{};ev('pointerdown',cx,cy);ev('pointermove',cx,cy-46);window.__up=()=>ev('pointerup',cx,cy)}""")
    m.wait_for_timeout(1500); m.evaluate("window.__up()")
    x1, z1 = m.evaluate("[agerous.player.x, agerous.player.z]")
    check('H5 joystick walks the player and releases cleanly', ((x1-x0)**2+(z1-z0)**2)**.5 > 0.5 and m.evaluate("agerous.player.joy.x === 0 && agerous.player.joy.y === 0"))
    m.fill('#prompt-input', 'A severe flood is coming'); m.click('#prompt-go'); m.wait_for_timeout(900)
    top = m.evaluate("document.getElementById('chain').getBoundingClientRect().top - document.getElementById('hud-top').getBoundingClientRect().bottom")
    check('H6 phone: consequence banner clears the top bar', top >= 0, round(top))
    m.screenshot(path=f'{shots}/10_mobile.png')
    # ---- Flow I: resilience — no WebGL, error toasts, URL parameters, AI chip, legend, 390px layout
    BASE = sys.argv[1]
    NOGL = "(() => { const g = HTMLCanvasElement.prototype.getContext; HTMLCanvasElement.prototype.getContext = function (t, ...a) { return /webgl/i.test(t) ? null : g.call(this, t, ...a); }; })();"
    for label, vp in (('desktop', {"width": 1360, "height": 800}), ('390px', {"width": 390, "height": 844})):
        c = b.new_context(viewport=vp, has_touch=(label == '390px'), is_mobile=(label == '390px')); c.add_init_script(NOGL)
        g = c.new_page(); gerr = []; g.on("pageerror", lambda e: gerr.append(str(e))); g.on("console", lambda m: gerr.append(m.text) if m.type == "error" and 'Failed to load resource' not in m.text else None)
        g.goto(BASE); g.wait_for_selector('#nogl:not(.hidden)', timeout=20000); g.wait_for_timeout(1200)
        check(f'I1 [{label}] WebGL off: full-screen fallback with headline', "3D isn't available in this browser" in g.inner_text('#nogl-title'))
        check(f'I2 [{label}] intro hidden, game UI hidden, demo GIF loaded, hardware-acceleration tip', g.evaluate("document.getElementById('intro').classList.contains('gone')") and not g.is_visible('#hud-top') and g.evaluate("document.getElementById('nogl-demo').naturalWidth") > 0 and 'hardware acceleration' in g.inner_text('#nogl').lower())
        check(f'I3 [{label}] WebGL off: no uncaught errors, no sideways scroll', not gerr and g.evaluate("document.documentElement.scrollWidth <= innerWidth"), '; '.join(gerr[:2]))
        check(f'I4 [{label}] intro/help handlers attached before the renderer', g.evaluate("['intro-play','intro-demo','btn-help'].every(i => typeof document.getElementById(i).onclick === 'function')"))
        g.screenshot(path=f'{shots}/11_nowebgl_{label}.png'); c.close()
    c = b.new_context(viewport={"width": 1360, "height": 800}); g = c.new_page()
    g.goto(BASE + '?play'); g.wait_for_function("window.agerous && window.agerous.world", timeout=45000); g.wait_for_timeout(800)
    check('I5 new world: wellbeing legend shows nothing yet', g.evaluate("['k-you','k-river'].every(i => document.getElementById(i).classList.contains('hidden'))"))
    check('I6 AI chip reads "Offline rules" with no key', g.inner_text('#ai-chip').strip() == 'Offline rules', g.inner_text('#ai-chip'))
    g.evaluate("setTimeout(() => { throw new Error('boom from a timer') }, 0)"); g.wait_for_timeout(500)
    check('I7 window.onerror -> visible toast', 'boom from a timer' in g.inner_text('#toasts'))
    g.evaluate("(() => { Promise.reject(new Error('async boom')); })()"); g.wait_for_timeout(500)
    check('I8 unhandledrejection -> visible toast', 'async boom' in g.inner_text('#toasts'))
    g.evaluate("setTimeout(() => { throw new Error('boom from a timer') }, 0)"); g.wait_for_timeout(400)
    check('I9 a repeated error is not shown twice', g.inner_text('#toasts').count('boom from a timer') == 1)
    g.screenshot(path=f'{shots}/12_toast.png')
    g.fill('#prompt-input', 'A severe flood is coming'); g.click('#prompt-go')
    g.wait_for_function("!document.getElementById('k-you').classList.contains('hidden')", timeout=15000)
    check('I10 legend names "your sentences" once you have typed one', True)
    g.evaluate("agerous.world.timeSpeed = 90"); g.wait_for_function("!document.getElementById('k-river').classList.contains('hidden')", timeout=30000)
    check('I11 legend names the river once it rises', True)
    g.evaluate("localStorage.setItem('agerous.ai', JSON.stringify({provider: 'openai', key: 'sk-test', model: 'm'}))"); g.reload(); g.wait_for_function("window.agerous && window.agerous.world", timeout=45000); g.wait_for_timeout(500)
    check('I12 AI chip reads "AI ready" once a key is saved', g.inner_text('#ai-chip').startswith('AI'), g.inner_text('#ai-chip'))
    g.fill('#prompt-input', 'heavy rain'); g.click('#prompt-go'); g.wait_for_function("document.getElementById('ai-chip').textContent.trim() === 'Offline rules'", timeout=20000)
    check('I13 chip drops to "Offline rules" when the AI call fails (and says why)', 'failed' in (g.get_attribute('#ai-chip', 'title') or ''))
    g.evaluate("localStorage.removeItem('agerous.ai')"); c.close()
    for q, js, name in (("?demo", "!document.getElementById('caption').classList.contains('hidden')", 'I14 ?demo skips the intro and runs the flood demo'),
                        ("?challenge", "!document.getElementById('drawer').classList.contains('hidden') && !document.getElementById('tab-challenge').classList.contains('hidden')", 'I15 ?challenge opens the Storm Day panel'),
                        ("?challenge=start", "!document.getElementById('chal-bar').classList.contains('hidden')", 'I16 ?challenge=start begins Storm Day'),
                        ("?play", "true", 'I17 ?play skips the intro')):
        c = b.new_context(viewport={"width": 1360, "height": 800}); g = c.new_page(); g.goto(BASE + q); g.wait_for_function("window.agerous && window.agerous.world", timeout=45000); g.wait_for_timeout(2500)
        check(name, g.evaluate(js) and g.evaluate("document.getElementById('intro').classList.contains('gone')")); c.close()
    c = b.new_context(viewport={"width": 1360, "height": 800}); g = c.new_page(); g.goto(BASE); g.wait_for_timeout(1500)
    check('I18 landing step 2 reads "Built-in rules (or your AI key) turn it into a validated event"', 'Built-in rules (or your AI key) turn it into a validated event' in g.inner_text('#intro'))
    g.click('#intro-play'); g.click('#btn-help')
    check('I19 Play closes the intro and ? reopens it', not g.evaluate("document.getElementById('intro').classList.contains('gone')")); c.close()
    c = b.new_context(viewport={"width": 390, "height": 844}, has_touch=True, is_mobile=True); g = c.new_page(); g.on("pageerror", lambda e: errors.append("390 PAGEERROR " + str(e)))
    g.goto(BASE); g.wait_for_function("window.agerous && window.agerous.world", timeout=45000); g.wait_for_timeout(600)
    check('I20 [390px] landing fits, no sideways scroll', g.evaluate("document.documentElement.scrollWidth <= innerWidth"))
    g.click('#intro-play'); g.wait_for_timeout(600)
    off = g.evaluate("""() => [...document.querySelectorAll('#hud-top button, #hud-top .ai-chip, #prompt-form *')].filter(e => { const r = e.getBoundingClientRect(); return r.width && (r.right > innerWidth + 0.5 || r.left < -0.5); }).map(e => e.id || e.className || e.tagName)""")
    check('I21 [390px] every top-bar and prompt control is fully on screen', not off, off)
    check('I22 [390px] AI chip visible beside the AI toggle, page does not scroll sideways', g.is_visible('#ai-chip') and g.evaluate("document.documentElement.scrollWidth <= innerWidth && document.body.scrollWidth <= innerWidth"))
    g.fill('#prompt-input', 'A severe flood is coming'); g.click('#prompt-go'); g.wait_for_function("!document.getElementById('chain').classList.contains('hidden')", timeout=20000)
    gap = g.evaluate("(() => { const c = document.getElementById('chain'); return c ? Math.round(c.getBoundingClientRect().top - document.getElementById('hud-top').getBoundingClientRect().bottom) : null; })()")
    check('I23 [390px] consequence banner sits below the top bar', gap is None or gap >= 0, gap)
    g.screenshot(path=f'{shots}/13_390_game.png')
    g.click('#btn-chal'); g.wait_for_timeout(500)
    check('I24 [390px] Storm Day drawer fits the screen and starts below the top bar', g.evaluate("(() => { const r = document.getElementById('drawer').getBoundingClientRect(); return r.left >= 0 && r.right <= innerWidth + 0.5 && r.bottom <= innerHeight + 0.5 && r.top >= document.getElementById('hud-top').getBoundingClientRect().bottom - 1; })()"))
    g.screenshot(path=f'{shots}/14_390_drawer.png'); c.close()
    check('no console errors', not errors, '; '.join(errors[:3]))
    b.close()
print('\nFAILED:', fails if fails else 'none'); sys.exit(1 if fails else 0)
